def set_cell_shading(cell, fill):
    tcPr=cell._tc.get_or_add_tcPr(); shd=tcPr.find(qn('w:shd'))
    if shd is None: shd=OxmlElement('w:shd'); tcPr.append(shd)
    shd.set(qn('w:fill'),fill)

def set_cell_margins(cell, top=100, start=120, bottom=100, end=120):
    tcPr=cell._tc.get_or_add_tcPr(); tcMar=tcPr.first_child_found_in('w:tcMar')
    if tcMar is None: tcMar=OxmlElement('w:tcMar'); tcPr.append(tcMar)
    for tag,val in [('top',top),('start',start),('bottom',bottom),('end',end)]:
        el=tcMar.find(qn('w:'+tag))
        if el is None: el=OxmlElement('w:'+tag); tcMar.append(el)
        el.set(qn('w:w'),str(val)); el.set(qn('w:type'),'dxa')

def set_table_geometry(table, widths):
    table.autofit=False
    tblPr=table._tbl.tblPr
    tblW=tblPr.find(qn('w:tblW'))
    if tblW is None: tblW=OxmlElement('w:tblW'); tblPr.append(tblW)
    tblW.set(qn('w:w'),str(sum(widths))); tblW.set(qn('w:type'),'dxa')
    tblInd=tblPr.find(qn('w:tblInd'))
    if tblInd is None: tblInd=OxmlElement('w:tblInd'); tblPr.append(tblInd)
    tblInd.set(qn('w:w'),'120'); tblInd.set(qn('w:type'),'dxa')
    grid=table._tbl.tblGrid
    for el in list(grid): grid.remove(el)
    for w in widths:
        gc=OxmlElement('w:gridCol'); gc.set(qn('w:w'),str(w)); grid.append(gc)
    for row in table.rows:
        for i,cell in enumerate(row.cells):
            tcPr=cell._tc.get_or_add_tcPr(); tcW=tcPr.find(qn('w:tcW'))
            if tcW is None: tcW=OxmlElement('w:tcW'); tcPr.append(tcW)
            tcW.set(qn('w:w'),str(widths[i])); tcW.set(qn('w:type'),'dxa')
            set_cell_margins(cell)

def set_repeat_header(row):
    trPr=row._tr.get_or_add_trPr(); e=OxmlElement('w:tblHeader'); e.set(qn('w:val'),'true'); trPr.append(e)

def set_para_rtl(p, align=WD_ALIGN_PARAGRAPH.RIGHT):
    p.alignment=align; pPr=p._p.get_or_add_pPr(); bidi=pPr.find(qn('w:bidi'))
    if bidi is None: bidi=OxmlElement('w:bidi'); pPr.append(bidi)
    bidi.set(qn('w:val'),'1')

def set_run(run, latin=False, size=11, bold=False, color=INK, italic=False):
    run.bold=bold; run.italic=italic; run.font.size=Pt(size); run.font.color.rgb=RGBColor.from_string(color)
    name=LATIN if latin else FA; run.font.name=name
    rPr=run._element.get_or_add_rPr()
    rFonts=rPr.rFonts
    if rFonts is None: rFonts=OxmlElement('w:rFonts'); rPr.insert(0,rFonts)
    for attr in ['ascii','hAnsi','cs','eastAsia']: rFonts.set(qn('w:'+attr),name)
    rtl=rPr.find(qn('w:rtl'))
    if rtl is None: rtl=OxmlElement('w:rtl'); rPr.append(rtl)
    rtl.set(qn('w:val'),'0' if latin else '1')

TOKEN=re.compile(r'\[\[([^\]]+)\]\]')
def add_mixed(p, txt, size=11, bold=False, color=INK):
    pos=0
    for m in TOKEN.finditer(txt):
        if m.start()>pos: set_run(p.add_run(txt[pos:m.start()]),False,size,bold,color)
        set_run(p.add_run('\u200e'+m.group(1)+'\u200e'),True,size,bold,color)
        pos=m.end()
    if pos<len(txt): set_run(p.add_run(txt[pos:]),False,size,bold,color)

def add_p(doc, txt='', size=11, bold=False, color=INK, before=0, after=6, line=1.25, keep=False, align=WD_ALIGN_PARAGRAPH.RIGHT):
    p=doc.add_paragraph(); set_para_rtl(p,align); pf=p.paragraph_format; pf.space_before=Pt(before); pf.space_after=Pt(after); pf.line_spacing=line; pf.keep_together=keep
    add_mixed(p,txt,size,bold,color); return p

def add_bullet(doc, txt):
    p=doc.add_paragraph(style='List Bullet'); set_para_rtl(p); p.paragraph_format.space_after=Pt(4); p.paragraph_format.line_spacing=1.25; p.paragraph_format.right_indent=Inches(.38); p.paragraph_format.first_line_indent=Inches(-.18); add_mixed(p,txt,11,False,INK); return p

def add_heading(doc, txt, level=1):
    p=doc.add_paragraph(style=f'Heading {level}'); set_para_rtl(p); add_mixed(p,txt,{1:16,2:13,3:12}[level],True,{1:NAVY,2:BLUE,3:GREEN}[level]); p.paragraph_format.keep_with_next=True; return p

def add_link(doc, label, target, note=''):
    p=doc.add_paragraph(); set_para_rtl(p); p.paragraph_format.space_after=Pt(4); p.paragraph_format.line_spacing=1.15
    set_run(p.add_run('مطالعهٔ بیشتر: '),False,10.5,True,GREEN)
    url='file://'+quote(str(ROOT/target))
    rid=p.part.relate_to(url,RELATIONSHIP_TYPE.HYPERLINK,is_external=True)
    h=OxmlElement('w:hyperlink'); h.set(qn('r:id'),rid); r=OxmlElement('w:r'); rPr=OxmlElement('w:rPr'); color=OxmlElement('w:color'); color.set(qn('w:val'),BLUE); u=OxmlElement('w:u'); u.set(qn('w:val'),'single'); rtl=OxmlElement('w:rtl'); rtl.set(qn('w:val'),'1'); rPr.extend([color,u,rtl]); t=OxmlElement('w:t'); t.text=label; r.extend([rPr,t]); h.append(r); p._p.append(h)
    if note: set_run(p.add_run(' — '+note),False,10.5,False,MUTED)

def callout(doc, label, text, fill=PALE_GREEN, color=GREEN):
    table=doc.add_table(rows=1,cols=1); table.alignment=WD_TABLE_ALIGNMENT.RIGHT; set_table_geometry(table,[9360]); set_repeat_header(table.rows[0]); cell=table.cell(0,0); set_cell_shading(cell,fill); cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    p=cell.paragraphs[0]; set_para_rtl(p); p.paragraph_format.space_after=Pt(0); p.paragraph_format.line_spacing=1.25
    set_run(p.add_run(label+'\n'),False,11,True,color); add_mixed(p,text,11.5,True,INK)
    add_p(doc,'',after=2,size=2)

def table(doc, headers, rows, widths, numeric_cols=()):
    t=doc.add_table(rows=1,cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.RIGHT; set_table_geometry(t,widths); set_repeat_header(t.rows[0])
    for i,h in enumerate(headers):
        c=t.rows[0].cells[i]; set_cell_shading(c,NAVY); p=c.paragraphs[0]; set_para_rtl(p,WD_ALIGN_PARAGRAPH.CENTER); add_mixed(p,h,9.5,True,WHITE)
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        if ri%2: [set_cell_shading(c,'F0F2F5') for c in cells]
        for i,v in enumerate(row):
            p=cells[i].paragraphs[0]; set_para_rtl(p,WD_ALIGN_PARAGRAPH.CENTER if i in numeric_cols else WD_ALIGN_PARAGRAPH.RIGHT); add_mixed(p,str(v),9.5,False,INK); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
    add_p(doc,'',after=2,size=2); return t

