add_p(doc,'در ارزیابی نسبی، پیش‌بینی هر تصویر با مقیاس و جابه‌جایی مناسب به مرجع هم‌تراز می‌شود. این روش شکل نسبی عمق را خوب می‌سنجد، اما همان مقیاس مطلقی را حذف می‌کند که اطلاعات دوربین قرار است فراهم کند. در ارزیابی متریک، چنین هم‌ترازی‌ای انجام نمی‌شود؛ بنابراین اثر فاصلهٔ کانونی قابل مشاهده می‌ماند. به همین دلیل، نتیجهٔ مدل بزرگ در ارزیابی نسبی تقریباً با کنترل مساوی شد، اما در آزمایش متریک و لرزش کانونی اثر [[K]] آشکار شد.')
add_link(doc,'کد ارزیابی مقاله','evaluate_paper.py','تقسیم داده، برش تصویر، دامنهٔ عمق و معیارها')
add_link(doc,'پیاده‌سازی معیارها','src/metrics.py','محاسبهٔ خطاها و برش مقادیر')

add_heading(doc,'۴. مسیر کامل پژوهش؛ از شکست تا نتیجه',1)
add_p(doc,'این بخش مهم‌ترین قسمت سند است. هر گام نشان می‌دهد که نتیجهٔ نهایی حاصل یک اجرای تصادفی نیست؛ بلکه با شناسایی و حذف توضیح‌های جایگزین ساخته شده است.',11.5,True,NAVY)
add_heading(doc,'۴.۱ پانزده گام اصلی آزمایش و اصلاح',2)
step(doc,'۱','ممیزی نقاط وارسی قدیمی','بیشتر اجراها ظاهراً همگرا بودند، اما چند اجرا خروجی نامعتبر، مقدار ثابت یا پیکسل‌های کاملاً صفر داشتند.','کاهش زیان یا ثبت یک امتیاز اعتبارسنجی، به‌تنهایی سلامت مدل را تضمین نمی‌کند.','خروجی واقعی، تعداد پیکسل‌های صفر و رفتار مدل‌های ذخیره‌شده مستقل از آموزش بررسی شد.','چند نتیجهٔ قدیمی از استدلال نهایی حذف شد و «شکست خاموش» به‌عنوان یک مسئلهٔ مستقل ثبت شد.')
step(doc,'۲','بازتولید خط مبنای منتشرشده','نتایج مدل منتشرشده روی دو مجموعه‌داده به اعداد مقاله نزدیک بود؛ برای نمونه، [[AbsRel]] مدل بزرگ روی [[NYUv2]] حدود ۰٫۰۴۲۵ شد.','زنجیرهٔ ارزیابی می‌توانست پروتکل مرجع را بازتولید کند؛ پس اختلاف‌های بعدی صرفاً از فرمول معیارها نبود.','پشتیبانی از مدل پایه و مدل بازنگری‌شده اضافه و برش تصویر، عمق خام و دامنهٔ ارزیابی اصلاح شد.','یک خط مبنای معتبر برای مقایسهٔ مدل منتشرشده، کنترل تنظیم‌شده و مدل پیشنهادی به دست آمد.')
step(doc,'۳','کشف نشت داده در NYUv2','۵۲۷ تصویر از ۶۵۴ تصویر آزمون، یعنی ۸۰٫۶ درصد، در تقسیم آموزش قدیمی حضور داشتند.','نتایج حاصل از آن تقسیم برای ادعای تعمیم معتبر نبودند.','ابتدا تمام تصاویر آزمون حذف و سپس ۷۹۵ تصویر باقی‌مانده به ۶۳۶ تصویر آموزش و ۱۵۹ تصویر اعتبارسنجی تقسیم شد.','نتایج نهایی روی تقسیم کاملاً بدون نشت تولید شدند.')
add_link(doc,'کد تقسیم بدون نشت','datasets/training_datasets.py','ساخت تقسیم آموزش و اعتبارسنجی')
step(doc,'۴','شکست تعمیم صفرنمونه','پس از تنظیم چندمجموعه‌ای، خطای [[KITTI]] از حدود ۰٫۰۸۳ به حدود ۰٫۲۱۴ رسید و دو بازوی پیشنهادی و کنترل تقریباً یکسان افت کردند.','تنظیم روی دادهٔ محدود و مصنوعی، دانش عمومی مدل بنیادین را تخریب کرده بود؛ اطلاعات دوربین علت این شکست نبود.','هدف «بهترشدن در صفرنمونه با تنظیم چندمجموعه‌ای» کنار گذاشته شد و آزمایش به یک پروتکل درون‌دامنه‌ای کنترل‌شده منتقل شد.','این مسیر به‌عنوان نتیجهٔ منفی ثبت شد: روش اولیه تعمیم صفرنمونه را بهتر نکرد.')
add_link(doc,'شرح ارزیابی صفرنمونه','explainations/شرح_جدول_4.5_ارزیابی_صفرنمونه.docx','جزئیات کامل اعداد و تفسیر')
step(doc,'۵','نخستین نتیجهٔ معتبر با مدل کوچک','روی تقسیم بدون نشت، مدل پیشنهادی به [[AbsRel=0.0501]] و [[RMSE=0.2064]] رسید؛ کنترل به‌ترتیب ۰٫۰۵۰۷ و ۰٫۲۰۸۸ بود.','در مقیاس کوچک، دسترسی به اطلاعات دوربین یک بهبود کوچک اما معنادار ایجاد می‌کرد.','همان آزمایش با مدل بزرگ‌تر تکرار شد تا پایداری اثر بررسی شود.','نخستین شاهد تمیز برای اثر [[K]] به دست آمد.')
step(doc,'۶','فروپاشی خاموش مدل بزرگ','خروجی هر دو بازوی مدل بزرگ از آغاز آموزش صفر شد و [[AbsRel]] نزدیک ۱ ماند. کاهش نرخ یادگیری و گرم‌کردن تدریجی کمکی نکرد.','ریشهٔ مشکل نرخ یادگیری نبود. مدل پایه خروجی معکوس عمق می‌داد، اما کد آموزش عمق مستقیم را هدف گرفته بود. فعال‌ساز نهایی نیز گرادیان را در صفر متوقف می‌کرد.','هدف آموزش به معکوس عمق تغییر کرد؛ ارزیابی با همان معنا هم‌سو شد و نوع فضای هدف در اطلاعات نقطهٔ وارسی ذخیره شد.','آزمایش کوتاه بدون پیکسل مرده اجرا شد و آموزش کامل مدل بزرگ ممکن گردید.')
add_link(doc,'کد آموزش و فضای هدف','train.py','ساخت هدف و محاسبهٔ زیان')
step(doc,'۷','نتیجهٔ مدل بزرگ پس از اصلاح','مدل پیشنهادی [[AbsRel=0.0377]] و کنترل ۰٫۰۳۷۸ گرفتند؛ هر دو از مدل منتشرشده بهتر بودند، اما اختلاف میان خودشان معنادار نبود.','تنظیم درون‌دامنه‌ای مفید بود، ولی در داده‌ای با دوربین تقریباً ثابت و ارزیابی نسبی، سهم خالص [[K]] دیده نمی‌شد.','دو احتمال بررسی شد: ناسازگاری [[K]] پس از برش تصویر، و حذف سیگنال مقیاس در هم‌ترازی نسبی.','این نتیجهٔ منفی، مسیر آزمایش را به افزونه‌سازی هندسی صحیح و سپس ارزیابی متریک هدایت کرد.')
step(doc,'۸','زوم و برش آگاه از دوربین','در برش تصادفی قدیمی، میدان دید تغییر می‌کرد ولی ماتریس دوربین ثابت می‌ماند.','تصویر و مشخصات دوربین با هم ناسازگار بودند؛ مدل گاهی اطلاعات نادرست دریافت می‌کرد.','پس از هر برش، تغییر اندازه و وارونه‌سازی افقی، چهار پارامتر اصلی ماتریس دوربین دقیقاً به‌روزرسانی شدند.','هر دو مدل بهتر شدند، اما اثر خالص [[K]] در ارزیابی نسبی هنوز روشن نبود. تنوع هندسی لازم بود، ولی کافی نبود.')
add_link(doc,'شرح تصویری افزونه‌سازی هندسی','explainations/شرح_بخش_3.7.7_افزونه_سازی_هندسی_آگاه_از_دوربین.docx','فرمول‌ها و مثال عددی')
step(doc,'۹','اصلاح سر مدل متریک','نقطهٔ وارسی متریک با یک نوع خروجی آموزش دیده بود، اما کد ارزیابی نمونه‌ای با فعال‌ساز متفاوت می‌ساخت.','یکسان‌بودن نام پارامترها برای سازگاری کافی نیست؛ معنای خروجی و فعال‌ساز نیز باید مطابق آموزش باشند.','کلاس درست برای نقاط وارسی متریک ساخته و منطق انتخاب مدل اصلاح شد.','ارزیابی متریک قابل اعتماد شد و دورهای بعدی دوباره معنا پیدا کردند.')
step(doc,'۱۰','دو دور ارزیابی متریک','با افزایش تنوع میدان دید، شکاف [[RMSE]] میان مدل پیشنهادی و کنترل از ۰٫۰۰۳۷ به ۰٫۰۰۵۴ افزایش یافت. در دور دوم، این اختلاف پس از تصحیح چندگانه نیز معنادار ماند.','وقتی هم‌ترازی مقیاس حذف شد و تنوع هندسی افزایش یافت، اثر اطلاعات دوربین منظم‌تر شد.','آزمایشی طراحی شد که در آن مقیاس از خود پیکسل‌ها قابل تشخیص نباشد و مدل برای پاسخ درست مجبور به استفاده از [[K]] شود.','زمینهٔ طراحی لرزش کانونی فراهم شد. نتیجهٔ [[AbsRel]] دور دوم پس از تصحیح چندگانه معنادار نماند و با احتیاط گزارش شد.')
add_link(doc,'گزارش اعتبارسنجی دور متریک','results/fresh_validation_4_5_6_20260807/validation_report.md','آزمون‌های زوجی و تصحیح چندگانه')
step(doc,'۱۱','لرزش کانونی؛ مداخلهٔ اصلی','در آزمایش‌های پیشین، مدل می‌توانست مقیاس را از اندازهٔ معمول اشیا و شکل اتاق حدس بزند و اطلاعات دوربین را کم‌استفاده نگه دارد.','باید پیکسل‌ها ثابت می‌ماندند، ولی عمق واقعی و فاصلهٔ کانونی با یک ضریب مشترک تغییر می‌کردند. در این حالت، ضریب فقط از طریق [[K]] قابل بازیابی است.','ضریب [[α]] در بازهٔ ۰٫۶۲۵ تا ۱٫۶ نمونه‌گیری شد. تصویر و نقطهٔ اصلی ثابت ماندند؛ فاصله‌های کانونی و عمق در همان ضریب ضرب شدند. بذر و جریان داده در دو بازو یکسان ماند.','مدل پیشنهادی در هر پنج معیار بهتر شد و تمام اختلاف‌ها پس از تصحیح [[Holm]] معنادار ماندند.')
add_link(doc,'شرح لرزش کانونی','explainations/شرح_بخش_3.7.8_افزونه_سازی_لرزش_کانونی.docx','منطق هندسی و جزئیات پیاده‌سازی')
add_link(doc,'شرح کامل دور سوم','explainations/شرح_کامل_بخش_4.5.7_دور_سوم_لرزش_کانونی.docx','روایت کامل آزمایش و آمار')
step(doc,'۱۲','آزمایش حذف عامل مزاحم','در دور سوم، لرزش کانونی و وزن یکی از اجزای زیان هم‌زمان تغییر کرده بودند.','بدون یک آزمایش حذف عامل، نمی‌شد مطمئن بود بهبود از لرزش کانونی آمده است.','یک زوج جدید با لرزش کانونی فعال و وزن زیان قبلی آموزش داده شد.','اثر باقی ماند و حتی قوی‌تر شد: [[AbsRel]] برابر ۰٫۰۸۳۴ در برابر ۰٫۱۰۶۵ و شیب پاسخ برابر ۰٫۹۷ شد. بنابراین عامل اصلی خود لرزش کانونی بود.')
step(doc,'۱۳','جاروی K؛ آیا مدل واقعاً K را می‌خواند؟','معیارهای کلی فقط می‌گفتند مدل بهتر شده است، اما نشان نمی‌دادند خروجی چقدر به فاصلهٔ کانونی واکنش دارد.','اگر مدل مطابق هندسه رفتار کند، تغییر لگاریتم عمق نسبت به تغییر لگاریتم فاصلهٔ کانونی باید شیبی نزدیک ۱ داشته باشد. شیب صفر یعنی بی‌تفاوتی کامل.','تصویر ثابت نگه داشته شد و فقط فاصله‌های کانونی با پنج ضریب تغییر کردند.','شیب مدل پیش از لرزش کانونی ۰٫۰۶ بود؛ پس از آن به ۰٫۹۳ و در آزمایش حذف عامل به ۰٫۹۷ رسید. شیب کنترل صفر بود.')
add_link(doc,'شرح سادهٔ آزمون جاروی K','explainations/شرح_بخش_4.5.1_آزمون_جاروی_K.docx','تفسیر شهودی و فرمول')
add_link(doc,'کد آزمون جاروی K','tools/k_sweep.py','اجرای آزمون روی تصاویر ثابت')
step(doc,'۱۴','حذف و تحریف اطلاعات دوربین','حساسیت خروجی به [[K]] به‌تنهایی ثابت نمی‌کرد که این اطلاعات برای دقت ضروری است.','باید تصویر ثابت می‌ماند و مقدار درست دوربین حذف یا عمداً اشتباه وارد می‌شد.','چهار حالت اجرا شد: [[K]] صحیح، [[K]] حذف‌شده، فاصلهٔ کانونی ضرب‌در ۰٫۷ و ضرب‌در ۱٫۴.','حذف [[K]]، خطای [[AbsRel]] را ۵۹ درصد افزایش داد. واردکردن فاصلهٔ کانونی نادرست، خطا را بسیار بیشتر کرد و جهت شکست با شیب آموخته‌شده سازگار بود.')
add_link(doc,'کد حذف و تحریف K','tools/k_knockout.py','آزمون ضرورت و حساسیت به کالیبراسیون')
step(doc,'۱۵','بازاعتبارسنجی مستقل','اعداد پایان‌نامه باید از خروجی تک‌تصویر، شناسه‌ها، اطلاعات نقاط وارسی و پروتکل ارزیابی دوباره محاسبه می‌شدند.','تطابق با یک خلاصهٔ ذخیره‌شده برای ممیزی علمی کافی نبود.','اسکریپت‌های اعتبارسنجی مستقل نوشته شدند و جفت‌سازی تصاویر، مقادیر نامتناهی، تعداد نمونه، برش تصویر، هم‌ترازی و تصحیح آزمون‌های متعدد را بررسی کردند.','نتایج اصلی دور سوم تأیید شدند. محدودیت اصلی همچنان یک بذر آموزشی برای هر بازو است.')
